<script setup>
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import api from '../api'
const list=ref([]),loading=ref(false),dialog=ref(false),drawer=ref(false),detail=ref({})
const statuses=['运行','停机','检修'],filters=ref({keyword:'',status:''}),form=ref({id:null,equipmentName:'',equipmentNo:'',status:'运行',lastMaintenanceDate:''})
async function load(){loading.value=true;try{list.value=await api.listEquipment(filters.value)}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
function open(row){form.value=row?{...row}:{id:null,equipmentName:'',equipmentNo:'',status:'运行',lastMaintenanceDate:''};dialog.value=true}
async function save(){try{form.value.id?await api.updateEquipment(form.value.id,form.value):await api.createEquipment(form.value);dialog.value=false;ElMessage.success('设备档案已保存');await load()}catch(e){ElMessage.error(e.message)}}
async function show(id){detail.value=await api.getEquipment(id);drawer.value=true}
onMounted(load)
</script>
<template><div class="page-card"><div class="toolbar"><div class="filters"><el-input v-model="filters.keyword" clearable placeholder="设备名或编号" style="width:210px"/><el-select v-model="filters.status" clearable placeholder="全部状态" style="width:130px"><el-option v-for="x in statuses" :key="x" :label="x" :value="x"/></el-select><el-button @click="load">筛选</el-button></div><el-button type="primary" @click="open()">新增设备</el-button></div><el-table :data="list" v-loading="loading" border stripe><el-table-column prop="equipmentName" label="设备名"/><el-table-column prop="equipmentNo" label="编号"/><el-table-column prop="status" label="状态"><template #default="{row}"><el-tag :type="row.status==='运行'?'success':row.status==='检修'?'danger':'info'">{{row.status}}</el-tag></template></el-table-column><el-table-column prop="lastMaintenanceDate" label="上次保养日期"/><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="show(row.id)">详情</el-button><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" :title="form.id?'编辑设备':'新增设备'" width="500px"><el-form :model="form" label-width="110px"><el-form-item label="设备名"><el-input v-model="form.equipmentName" placeholder="杀青机/揉捻机/烘干机"/></el-form-item><el-form-item label="设备编号"><el-input v-model="form.equipmentNo"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status" style="width:100%"><el-option v-for="x in statuses" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="上次保养日期"><el-date-picker v-model="form.lastMaintenanceDate" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-drawer v-model="drawer" title="设备档案详情" size="420px"><dl class="detail-grid"><template v-for="(v,k) in detail" :key="k"><dt>{{k}}</dt><dd>{{v??'-'}}</dd></template></dl></el-drawer></div></template>
